#!/usr/bin/env bash
# Merges the OpenAPI parts generated by each sub-module (target/openapi-parts/*.yaml)
# into one file per module, target/<module>_swagger.yaml, served under "/":
#  - a module is merged only when it has one part per generation plugin its pom declares,
#    so that a module whose Spring or JAX-RS generation failed is never published half;
#  - each part's paths are prefixed with that part's first server url, if any
#    (the JAX-RS part declares /rest; the Spring part already carries /<webapp>/rest);
#  - the parts are merged (paths, tags, components) and the servers set to "/";
#  - schema properties are sorted: kbuntrock lists them in no stable order, and the weekly
#    commit must only carry real changes.
# A module that cannot be merged is reported and skipped; the others are still merged, and
# the script then exits 1.
# Usage: merge.sh [module...]   (default: every sub-module of openapi/pom.xml). Requires yq v4.
set -uo pipefail
shopt -s nullglob

cd "$(dirname "$0")"
version=$(sed -n 's:.*<platform.version>\(.*\)</platform.version>.*:\1:p' pom.xml)
modules=("$@")
if [ ${#modules[@]} -eq 0 ]; then
  mapfile -t modules < <(sed -n 's:.*<module>\(.*\)</module>.*:\1:p' pom.xml)
fi

merge_module() {
  local module=$1
  local parts_dir="$module/target/openapi-parts"
  local output="$module/target/${module}_swagger.yaml"
  local expected sources part prefixed title
  local parts=()
  expected=$(grep -c '<artifactId>\(swagger-maven-plugin\|openapi-maven-plugin\)</artifactId>' "$module/pom.xml")
  sources=("$parts_dir"/*.yaml)
  if [ "${#sources[@]}" -ne "$expected" ]; then
    echo "::error::$module: ${#sources[@]} generated part(s), $expected expected"
    return 1
  fi
  for part in "${sources[@]}"; do
    prefixed="${part%.yaml}.prefixed"
    yq '(.servers[0].url // "") as $prefix
        | .paths |= with_entries(.key = $prefix + .key)
        | del(.servers)' "$part" > "$prefixed" || return 1
    parts+=("$prefixed")
  done
  title=$(sed -n 's:.*<openapi.title>\(.*\)</openapi.title>.*:\1:p' "$module/pom.xml")
  title="${title:-${module^} REST API}"
  # Maps are merged deeply; tags are concatenated, then deduplicated by name.
  TITLE="$title" VERSION="$version" yq eval-all \
    '. as $part ireduce ({}; (.tags // []) as $tags | . * $part | .tags = $tags + ($part.tags // []))
     | .tags |= unique_by(.name)
     | del(.tags | select(length == 0))
     | .openapi = "3.0.1"
     | .info = {"title": strenv(TITLE), "version": strenv(VERSION),
                "license": {"name": "LGPL", "url": "https://www.gnu.org/licenses/lgpl-3.0.en.html"}}
     | .servers = [{"url": "/"}]
     | with(select(.components.schemas != null);
            (.components.schemas[] | select(has("properties")) | .properties) |= sort_keys(.))' \
    "${parts[@]}" > "$output" || return 1
  rm -f "${parts[@]}"
  echo "$output: $(yq '.paths | length' "$output") paths"
}

status=0
for module in "${modules[@]}"; do
  merge_module "$module" || { echo "::error::$module: not merged"; status=1; }
done
exit $status
